'use strict';
const C=AtlasCore,$=id=>document.getElementById(id), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=x=>{try{const u=new URL(x);return u.protocol==='https:'?u.href:'#';}catch{return '#';}};
const link=(url,label)=>`<a href="${esc(safeURL(url))}" target="_blank" rel="noreferrer">${esc(label)}</a>`;
let DATA,STATE={schemaVersion:1,lineups:[],accounts:[],activeAccount:''},view='library',page=1,selectedMembers=[],galleryLimit=40,worker=null,matchResults={},currentCodeResult=null,currentDialog=null,detailState='unawakened',toastTimer,sessionRevision=0,appBoot=Promise.resolve();
const todayCN=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const account=()=>STATE.accounts.find(a=>a.id===STATE.activeAccount);
const lineups=()=>{const map=new Map(DATA.lineups.map(l=>[l.id,l]));for(const l of STATE.lineups)map.set(l.id,l);return [...map.values()].filter(C.hasLineupCode);};
function toast(message){if($('detail-dialog').open){$('dialog-feedback').textContent=message;$('dialog-feedback').hidden=false;}$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5000);}
async function browserDB(action,value){return new Promise((resolve,reject)=>{const r=indexedDB.open('onmyoji-atlas',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onerror=()=>reject(r.error);r.onsuccess=()=>{const db=r.result,t=db.transaction('state',action==='get'?'readonly':'readwrite'),s=t.objectStore('state'),q=action==='get'?s.get('main'):s.put(value,'main');q.onerror=()=>reject(q.error);t.oncomplete=()=>{db.close();resolve(q.result);};t.onerror=()=>reject(t.error);};});}
const sameSession=revision=>revision===sessionRevision&&window.TALogin?.status().authenticated===true;
async function persist(){const revision=sessionRevision;try{if(!sameSession(revision))return false;if(window.atlas)await atlas.saveState(STATE);else await browserDB('put',STATE);return sameSession(revision);}catch(e){if(sameSession(revision))toast('保存失败：'+e.message+'。请立即导出备份。');return false;}}
async function copyCode(button,code){
 if(!C.hasLineupCode({code}))return toast('没有可复制的阵容码');
 const label=button.dataset.copyLabel||button.textContent;button.dataset.copyLabel=label;button.disabled=true;button.dataset.copyState='copying';button.textContent='复制中…';
 try{
  if(window.atlas?.copyCode){const result=await atlas.copyCode(code);if(!result?.copied)throw new Error('未完成剪贴板写入');}
  else{
   try{if(!navigator.clipboard?.writeText)throw new Error('剪贴板接口不可用');await navigator.clipboard.writeText(code);}
   catch{const input=document.createElement('textarea');input.className='clipboard-transfer';input.value=code;input.setAttribute('aria-label','待复制的阵容码');($('detail-dialog').open?$('detail-dialog'):document.body).append(input);const focused=document.activeElement;try{input.select();if(!document.execCommand('copy'))throw new Error('浏览器未允许复制');}finally{input.remove();focused?.focus();}}
  }
  button.dataset.copyState='success';button.textContent='已复制';toast('原始阵容码已复制');
 }catch(e){button.dataset.copyState='failed';button.textContent=label;toast('复制失败：'+e.message+'。可选中详情顶部的原码手动复制。');}
 finally{button.disabled=false;}
}
function selectView(name){view=name;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!=='view-'+name);document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===name));$('page-title').textContent={library:'PVE 阵容库',decode:'阵容码查看',accounts:'我的账号',gallery:'式神图鉴',audit:'来源与覆盖'}[name];if(name==='library')renderLibrary();if(name==='gallery')renderGallery();if(name==='accounts')renderAccounts();if(name==='audit')renderAudit();window.scrollTo(0,0);}
function rosterById(id){return DATA.roster.find(r=>r.id===String(id));}
function actorFor(m){return (DATA.actors||[]).find(a=>(m.onmyojiId&&a.gameId!=null&&String(a.gameId)===m.onmyojiId)||a.name===m.name||a.aliases?.includes(m.name));}
function resourceFor(m){return m.kind==='onmyoji'?actorFor(m):rosterById(m.shikigamiId);}
function variant(r,state,kind='art'){if(r?.sourceRegion)state='unawakened';if(state==='awakened'&&r?.assets?.awakeningAvailability==='not_applicable')return null;return r?.assets?.variants?.find(a=>a.family===`${kind==='art'?'art':'portrait'}-${state==='awakened'?'after':'before'}`&&a.status==='downloaded_valid_image');}
function imagePath(a){if(a&&/^[a-f0-9]{64}\.(png|jpg)$/.test(a.cacheFile))return window.atlas?'atlas-asset://cache/'+a.cacheFile:'/cache/'+a.cacheFile;return a&&/^data\/images\/(?:\d+|actors\/[a-z]+)\/[a-z-]+\.(png|jpg)$/.test(a.localPath)?'../'+a.localPath:null;}
function thumb(m,state){const r=resourceFor(m),s=r?.assets?.awakeningAvailability==='not_applicable'?'unawakened':m.awakening===1?'awakened':m.awakening===0?'unawakened':state||'unawakened',a=variant(r,s,'portrait')||(m.kind==='onmyoji'?variant(r,s):null),src=imagePath(a);return src?`<img class="avatar" src="${src}" alt="${esc(m.name||r.name)} · ${esc(a.sourceLabel||'官方')}${a.family.startsWith('portrait')?'头像':'立绘缩略展示'}" loading="lazy">`:`<div class="avatar-placeholder" title="${esc(m.name||'成员未解析')} · 图片未收录">${m.name?esc(m.name[0]):'?'}</div>`;}
function heroTeam(l){let members=l.members?.filter(m=>m.occupied!==false)||[];if(!members.length)members=[...Array.from({length:5},(_,i)=>({name:'待解析',index:i,unknown:true})),{kind:'onmyoji',name:'未指定'}];return `<div class="team-thumbs">${members.map(m=>`<div class="team-member ${m.kind==='onmyoji'?'onyo':''}" title="${esc(m.name)}">${m.unknown?'<div class="avatar-placeholder">?</div>':thumb(m)}<span>${esc(m.name)}</span></div>`).join('')}</div>`;}
function badge(l){const result=matchResults[l.id];if(result)return `<span class="badge ${result.status==='missing'?'bad':result.status==='available'?'good':'warning'}">${esc(result.label)}</span>`;return `<span class="badge ${l.members?.length?'':'warning'}">${l.decodeState==='decoded-server'?'官方查询已解析':l.decodeState==='decoded-local'?'本地已解析':l.members?.length?(l.sourceKind==='manual'?'手工配置':'参考方案'):'待解析'}</span>`;}
function filteredLineups(){const query=$('search').value.trim().toLowerCase().split(/\s+/).filter(Boolean),category=$('category').value,dungeon=$('dungeon').value,source=$('source-filter').value,status=$('status-filter').value;return lineups().filter(l=>{
 if(category&&l.category!==category)return false;if(dungeon&&!(l.dungeons||[l.dungeon]).includes(dungeon)&&l.dungeon!==dungeon)return false;
 if(source==='excel'&&l.sourceKind!=='excel')return false;if(source==='web'&&!l.sourceKind?.startsWith('web'))return false;if(source==='user'&&!STATE.lineups.some(x=>x.id===l.id))return false;
 if(status==='structured'&&!l.members?.length)return false;if(status==='pending'&&l.members?.length)return false;if(['available','missing','unknown'].includes(status)&&matchResults[l.id]?.status!==status)return false;
 if(!selectedMembers.every(id=>l.members?.some(m=>m.shikigamiId===id)))return false;
 const text=JSON.stringify(l).toLowerCase();return query.every(q=>text.includes(q));
});}
function renderLibrary(){const ls=filteredLineups();page=Math.max(1,Math.min(page,Math.ceil(ls.length/24)||1));const shown=ls.slice((page-1)*24,page*24);
 $('results-count').textContent=`找到 ${ls.length} 个阵容${selectedMembers.length?' · 不含成员未知的记录':''}`;
 $('lineup-grid').innerHTML=shown.length?shown.map(l=>`<article class="lineup-card"><div class="card-head"><div><h3>${esc(l.title)}</h3><p class="card-subtitle">${esc(l.category)} / ${esc(l.dungeon)}${l.date?' · '+esc(l.date.slice(0,10)):''}</p></div>${badge(l)}</div>${heroTeam(l)}<div class="card-footer"><code class="code" title="${esc(l.code||'来源未提供阵容码')}">${esc(l.code||'来源未提供阵容码')}</code>${l.code?`<button class="copy-code" data-copy="${esc(l.id)}">复制</button>`:''}<button class="secondary" data-detail="${esc(l.id)}">详情</button></div></article>`).join(''):'<div class="empty">没有符合条件的阵容。<br>试试减少关键词或取消部分筛选。</div>';
 $('page-indicator').textContent=`${page} / ${Math.ceil(ls.length/24)||1}`;$('previous-page').disabled=page===1;$('next-page').disabled=page*24>=ls.length;$('match-all').disabled=!account()||!!worker;
 $('nav-count').textContent=lineups().length;$('stat-lineups').textContent=lineups().length;$('stat-dungeons').textContent=new Set(lineups().flatMap(l=>l.dungeons||[l.dungeon])).size;$('stat-reference').textContent=lineups().filter(l=>l.members?.length).length;
 const active=DATA.events.filter(e=>e.start<=todayCN()&&e.end>=todayCN()&&e.battle);$('event-strip').innerHTML=active.length?`<div class="event-banner"><div><strong>${esc(active[0].title)} · 进行中</strong><span>截至 ${esc(active[0].end)} · 国服活动公告已核对</span></div><button class="ghost" id="event-filter">查看活动阵容 →</button></div>`:'';
}
function fillFilters(){const ls=lineups(),cats=[...new Set(ls.map(x=>x.category))],dungeons=[...new Set(ls.flatMap(x=>x.dungeons||[x.dungeon]))].sort((a,b)=>a.localeCompare(b,'zh'));const update=(el,values,label)=>{const previous=el.value;el.innerHTML=`<option value="">${label}</option>`+values.map(v=>`<option>${esc(v)}</option>`).join('');el.value=values.includes(previous)?previous:'';};update($('category'),cats,'全部分类');update($('dungeon'),dungeons,'全部副本');$('hero-options').innerHTML=DATA.roster.map(r=>`<option value="${esc(r.name)}">${esc(r.rarity)} · ${r.id}</option>`).join('');}
function renderSelected(){$('selected-members').innerHTML=selectedMembers.map(id=>`<span class="chip">${esc(rosterById(id)?.name||id)}<button data-remove-member="${id}" aria-label="移除式神筛选">×</button></span>`).join('');}
function updateAccountSelect(){const selected=STATE.activeAccount;$('active-account').innerHTML='<option value="">选择账号检查配置</option>'+STATE.accounts.map(a=>`<option value="${esc(a.id)}">${esc(a.name)} · ${esc(a.server)}</option>`).join('');$('active-account').value=selected;}
function openDialog(title,subtitle,body){$('dialog-feedback').hidden=true;$('dialog-heading').innerHTML=`<h2>${esc(title)}</h2><p>${esc(subtitle)}</p>`;$('dialog-body').innerHTML=body;if(!$('detail-dialog').open)$('detail-dialog').showModal();}
function propertyText(c){if(!c)return '未提供';return (c.ranges||[]).map(r=>[(C.STAT_NAMES[r.stat]||r.stat),r.min!=null?(r.minExclusive?'>':'≥')+r.min+(r.percentage?'%':''):'',r.max!=null?(r.maxExclusive?'<':'≤')+r.max+(r.percentage?'%':''):''].filter(Boolean).join(' ')).join('；')||'未指定';}
function configText(c){if(!c)return '未提供';return c.suitRequirements?.map(r=>`${r.name} ${r.count}件`).join(' + ')||c.suits?.join(' + ')||(c.suitSelectionComplete?'散件':'未指定');}
function mainText(c){return c?Object.entries(c.mainStats||{}).map(([slot,stats])=>`${slot}号位：${stats.map(s=>C.STAT_NAMES[s]||s).join(' / ')}`).join('；')||'未指定':'未提供';}
function protocolDetails(m){
 const p=m.config?.protocol,labels={debuff_res:'效果抵抗',critical_rate:'暴击',final_atk:'攻击',debuff_acc:'效果命中',final_max_hp:'生命',critical_pow:'暴击伤害',spd:'速度',final_def:'防御',ExtraAttr:'额外属性'};
 const range=v=>Array.isArray(v)?v.map(x=>typeof x==='object'?JSON.stringify(x):String(x)).join(' ～ '):typeof v==='object'?JSON.stringify(v):String(v);
 if(!p&&!m.qiling&&m.aiSkill==null)return '';
 return `<details class="protocol-fields" open><summary>阵容码原始配置</summary><dl>${p?`<dt>御魂等级 / 星级</dt><dd>${esc(range(p.yuhunLevel||[]))}级 / ${esc((p.yuhunStars||[]).join('、'))}星</dd><dt>计算指标 criteria</dt><dd>${esc(p.criteria??'未提供')}（业务枚举待核对）</dd><dt>两件套属性</dt><dd>${esc(p.twoSuit.join('、')||'未指定')}</dd>${Object.entries(p.limits).map(([k,v])=>`<dt>${esc(labels[k]||k)}（原值）</dt><dd>${esc(range(v))}</dd>`).join('')}<dt>最高属性</dt><dd>${esc(p.highest.join('、')||'未指定')}</dd><dt>计算开关 / 评分</dt><dd>not_calc_flag: ${esc(p.notCalcFlag??'未提供')} / use_score: ${esc(p.useScore??'未提供')}</dd>`:''}${m.qiling?`<dt>契灵</dt><dd>ID ${esc(m.qiling.id)} · ${esc(m.qiling.star)}星 · ${esc(m.qiling.lv)}级</dd><dt>契灵印记</dt><dd>${esc((m.qiling.marks||[]).join('、'))}</dd>`:''}${m.aiSkill!=null?`<dt>自动技能 ai_skill</dt><dd>${esc(range(m.aiSkill))}</dd>`:''}</dl>${p?'<p class="caption">保留游戏编码的原始数值与精度。未核实的单位、枚举和套装组合语义暂不参与御魂可用判定。</p>':''}</details>`;
}
function memberDetail(m){const r=resourceFor(m),noAwake=r?.assets?.awakeningAvailability==='not_applicable',state=noAwake?'unawakened':m.awakening===1?'awakened':m.awakening===0?'unawakened':detailState,a=variant(r,state),src=imagePath(a),c=m.config;
 const reason=m.kind==='onmyoji'?'阴阳师 / 英杰形象尚未收录':state==='awakened'&&r?.assets?.awakeningAvailability==='not_applicable'?'官方资料显示无独立觉醒形态':'该状态的官方立绘尚未取得';
 return `<article class="member-detail"><div class="large-art">${src?`<img src="${src}" alt="${esc(m.name)} · ${esc(a.sourceLabel||'官方')}立绘">`:`<span>${esc(reason)}<br>原生卡面未核验</span>`}</div><div class="detail-member-head">${thumb(m,state)}<div><strong>${esc(m.name)}</strong><p>${esc(r?.rarity||(m.kind==='onmyoji'?'阴阳师 / 英杰':''))} ${m.onmyojiId?'ID '+esc(m.onmyojiId):m.shikigamiId?'ID '+esc(m.shikigamiId):''}</p></div></div><div class="member-fields"><dl><dt>形象</dt><dd>${src?esc(a.sourceLabel||'国服官方')+'立绘 · 原生卡面未核验':'资源缺失'}</dd><dt>觉醒</dt><dd>${m.kind==='onmyoji'?'主角默认形象':noAwake?'无独立觉醒形态 · 展示默认形象':m.awakening===0?'要求未觉醒':m.awakening===1?'要求觉醒':'阵容未指定 · 展示'+(state==='awakened'?'觉醒':'未觉醒')+'形象'}</dd><dt>技能</dt><dd>${m.skills?.length?m.skills.map(s=>`${s.id} ${s.exact?'=':'≥'}${s.level}级`).join('；'):'未提供技能等级要求'}</dd><dt>等级星级</dt><dd>${m.level?'≥'+m.level+'级':'等级未指定'} / ${m.star?'≥'+m.star+'星':'星级未指定'}</dd><dt>御魂</dt><dd>${esc(configText(c))}</dd><dt>主属性</dt><dd>${esc(mainText(c))}</dd><dt>数值条件</dt><dd>${c?.protocol?'见下方阵容码原始配置':esc(propertyText(c))}</dd><dt>计算指标</dt><dd>${c?.protocol?'原始 criteria: '+esc(c.protocol.criteria??'未提供'):esc(C.METRICS[c?.metricId]?.[0]||(c?.metricId?'未知指标 '+c.metricId:'未指定'))}${c?.targetScore!=null?' ≥ '+esc(c.targetScore):''}</dd><dt>额外属性</dt><dd>${c?.protocol?'见下方原始额外属性':c?.extraAttributes?esc(Object.entries(c.extraAttributes).map(([k,v])=>`${C.STAT_NAMES[k]||k}: ${v}${['attackPercent','crit','critDamage'].includes(k)?'（小数比例）':''}`).join('；')):'未提供'}</dd><dt>补充要求</dt><dd>${esc(m.notes||'无已核实的补充要求')}</dd></dl>${protocolDetails(m)}${a?`<p class="caption">${a.width} × ${a.height} · ${esc(a.sourceLabel||'网易国服官网')} · ${esc(a.verifiedState?'来源映射已核对':'形态待核对')}</p><span class="source-link">${link(a.sourcePage||a.url,'查看图片来源')}</span>`:''}</div></article>`;
}
function showLineup(l){currentDialog=l;const result=matchResults[l.id];const body=`<div class="detail-actions"><code class="mono small">${esc(l.code||'此参考方案没有阵容码')}</code><div><select id="detail-state" aria-label="未指定觉醒时的展示形态"><option value="unawakened" ${detailState==='unawakened'?'selected':''}>未指定者展示未觉醒</option><option value="awakened" ${detailState==='awakened'?'selected':''}>未指定者展示觉醒</option></select> <button id="copy-lineup" class="primary">复制阵容码</button> <button id="parse-lineup" class="secondary">${l.members?.length?'重新解析':'解析此阵容码'}</button> <button id="export-lineup" class="secondary">导出资料</button></div></div>${!l.members?.length?`<div class="notice"><strong>尚未还原阵容成员</strong><br>${esc(l.decodeError||'未取得该原码的成功解析响应。')}<br>此处没有可验证的式神、技能、御魂或数值要求。原码、用途、备注和来源已经保存。</div>`:''}${l.members?.length?'<div class="formation-heading"><h3>出战式神与阴阳师</h3><div class="formation-controls"><span>按槽位排列</span><button id="scroll-members-left" class="secondary" aria-label="查看左侧成员">←</button><button id="scroll-members-right" class="secondary" aria-label="查看右侧成员">→</button></div></div>':''}<div class="member-detail-grid" aria-label="阵容成员并排配置" tabindex="0">${(l.members||[]).filter(m=>m.occupied!==false).map(memberDetail).join('')}</div><div class="detail-section"><h3>操作、配速与备注</h3><p class="detail-notes">${esc(l.notes||'来源未提供补充说明。')}</p>${(l.warnings||[]).map(w=>`<p class="caption">${esc(w)}</p>`).join('')}</div><div class="detail-section"><h3>替代式神与要求</h3><p>${esc(l.alternatives||'来源未提供经过核实的替代配置。不会按定位相近自动当作可替换。')}</p></div>${result?`<div class="detail-section"><h3>账号核对：${esc(result.label)}</h3>${result.reasons.map(r=>`<p>${esc(r)}</p>`).join('')}${result.members.map(m=>`<details><summary>${esc(m.name)} · ${esc({found:'已找到库存方案',missing:'存在缺口',unknown:'尚待核对'}[m.status]||m.status)}</summary><p>${esc(m.reasons?.join('；')||'已满足已知御魂条件')}</p>${m.builds?.[0]?`<pre class="json">${esc(JSON.stringify(m.builds[0],null,2))}</pre>`:''}</details>`).join('')}${result.assignment?.length?`<details><summary>全队候选分配（御魂与式神实例不重复）</summary><pre class="json">${esc(JSON.stringify(result.assignment,null,2))}</pre></details>`:''}</div>`:''}<div class="detail-section"><h3>来源与适用范围</h3><p>${l.sourceUrl?link(l.sourceUrl,l.author||l.sourceUrl):'用户提供的 Excel / 本地配置'}</p>${l.date?`<p class="caption">原文日期：${esc(l.date)}。历史方案未自动视为当前版本最优。</p>`:''}${l.occurrences?.length?`<p class="caption">${l.occurrences.map(o=>esc(`${o.sheet} 第${o.row}行：${o.title}`)).join('<br>')}</p>`:''}${l.webSources?.map(s=>`<p class="caption">${link(s.url,s.title)}</p>`).join('')||''}</div><details class="detail-section"><summary>完整结构化资料 JSON</summary><pre class="json">${esc(JSON.stringify(l,null,2))}</pre></details>`;openDialog(l.title,`${l.category||'本地资料'} / ${l.dungeon||'待分类'} · 槽位顺序不等于出手顺序`,body);}
function renderGallery(){const actors=$('gallery-kind').value==='actors';for(const id of ['rarity-filter','include-sp','tag-filter','gallery-state'])$(id).disabled=actors;if(actors)return renderActors();const query=$('gallery-search').value.trim(),rarity=$('rarity-filter').value,sp=$('include-sp').checked||rarity==='SP',tag=$('tag-filter').value,state=$('gallery-state').value;const rows=DATA.roster.filter(r=>(!query||(r.name+' '+r.id).includes(query))&&(!rarity||r.rarity===rarity)&&(sp||r.rarity!=='SP')&&(!tag||(tag==='collab'?r.isCollaboration:tag==='gua'?r.isGua:r.isMaterial))).sort((a,b)=>Number(b.id)-Number(a.id));$('gallery-count').textContent=`${rows.length} 个目录条目 · 已审计形态 ${DATA.assetAudit.charactersAudited}/${DATA.roster.length} · 原生卡面核验 0`;const shown=rows.slice(0,galleryLimit);$('gallery-grid').innerHTML=shown.map(r=>{const a=variant(r,state),src=imagePath(a);return `<article class="gallery-card" data-hero="${r.id}" tabindex="0" role="button" aria-label="查看${esc(r.name)}形象资料"><div class="gallery-art">${src?`<img src="${src}" alt="${esc(r.name)}官方立绘" loading="lazy">`:`<p class="missing-art">${state==='awakened'&&r.assets?.awakeningAvailability==='not_applicable'?'无独立觉醒形态':'该形態资源待补充'}<br>原生卡面未核验</p>`}</div><div class="gallery-info">${thumb({shikigamiId:r.id,name:r.name},state)}<div><strong>${esc(r.name)}</strong><p>#${r.id} ${r.isCollaboration?'· 联动 ':''}${r.isGua?'· 呱 ':''}${r.isMaterial?'· 素材 ':''}</p></div><span class="rarity">${esc(r.rarity)}</span></div></article>`;}).join('')||'<div class="empty">没有符合筛选条件的式神</div>';$('more-gallery').hidden=rows.length<=galleryLimit;}
